sp_widget.client_script:
api.controller = function($scope, $window, $location) {

    var c = this;


    // ============================================================
    // INTERVIEW SYS_ID
    // ============================================================

    c.interviewSysId =
        $location.search().interview_sys_id;


    // ============================================================
    // FORM
    // ============================================================

    c.form = {

        technical_score: "",

        problem_solving_score: "",

        communication_score: "",

        recommendation: "",

        evaluation_feedback: ""

    };


    // ============================================================
    // UI STATE
    // ============================================================

    c.saving = false;

    c.error = "";

    c.success = "";

    c.overallScore = 0;


    // ============================================================
    // CALCULATE OVERALL SCORE
    // ============================================================

    c.calculateScore = function() {

        var technical =
            parseInt(
                c.form.technical_score || 0,
                10
            );


        var problemSolving =
            parseInt(
                c.form.problem_solving_score || 0,
                10
            );


        var communication =
            parseInt(
                c.form.communication_score || 0,
                10
            );


        var total =
            technical +
            problemSolving +
            communication;


        /*
         * No scores selected
         */

        if (
            technical === 0 &&
            problemSolving === 0 &&
            communication === 0
        ) {

            c.overallScore = 0;

            return;

        }


        /*
         * 3 categories × 5 = 15
         *
         * Convert to 100
         */

        c.overallScore =
            Math.round(
                (total / 15) * 100
            );

    };


    // ============================================================
    // WATCH SCORE CHANGES
    // ============================================================

    $scope.$watchGroup(
        [
            "c.form.technical_score",
            "c.form.problem_solving_score",
            "c.form.communication_score"
        ],
        function() {

            c.calculateScore();

        }
    );


    // ============================================================
    // BACK
    // ============================================================

    c.goBack = function() {

        $window.location.href =
            "?id=campus360_recruiter_interviews";

    };


    // ============================================================
    // SUBMIT EVALUATION
    // ============================================================

    c.submitEvaluation = function() {

        /*
         * Prevent duplicate clicks
         */

        if (c.saving) {

            return;

        }


        /*
         * Clear previous messages
         */

        c.error = "";

        c.success = "";


        // ========================================================
        // VALIDATE SYS_ID
        // ========================================================

        if (!c.interviewSysId) {

            c.error =
                "Interview record ID is missing.";

            return;

        }


        // ========================================================
        // VALIDATE TECHNICAL SCORE
        // ========================================================

        if (
            !c.form.technical_score ||
            c.form.technical_score < 1 ||
            c.form.technical_score > 5
        ) {

            c.error =
                "Please provide a Technical Skills rating.";

            return;

        }


        // ========================================================
        // VALIDATE PROBLEM SOLVING
        // ========================================================

        if (
            !c.form.problem_solving_score ||
            c.form.problem_solving_score < 1 ||
            c.form.problem_solving_score > 5
        ) {

            c.error =
                "Please provide a Problem Solving rating.";

            return;

        }


        // ========================================================
        // VALIDATE COMMUNICATION
        // ========================================================

        if (
            !c.form.communication_score ||
            c.form.communication_score < 1 ||
            c.form.communication_score > 5
        ) {

            c.error =
                "Please provide a Communication Skills rating.";

            return;

        }


        // ========================================================
        // VALIDATE RECOMMENDATION
        // ========================================================

        if (
            !c.form.recommendation ||
            c.form.recommendation === "select"
        ) {

            c.error =
                "Please select a recommendation.";

            return;

        }


        // ========================================================
        // VALIDATE FEEDBACK
        // ========================================================

        if (
            !c.form.evaluation_feedback ||
            !String(
                c.form.evaluation_feedback
            ).trim()
        ) {

            c.error =
                "Please enter interview feedback.";

            return;

        }


        // ========================================================
        // CALCULATE SCORE
        // ========================================================

        c.calculateScore();


        // ========================================================
        // START SAVING
        // ========================================================

        c.saving = true;


        // ========================================================
        // SEND TO SERVER
        // ========================================================

        c.data.action =
            "save_evaluation";


        c.data.interview_sys_id =
            c.interviewSysId;


        c.data.form =
            angular.copy(c.form);


        // ========================================================
        // SERVER UPDATE
        // ========================================================

        c.server.update().then(

            function(response) {

                c.saving = false;


                /*
                 * Safety check
                 */

                if (!response) {

                    c.error =
                        "No response received from ServiceNow.";

                    return;

                }


                /*
                 * Successful save
                 */

                if (
                    response.data &&
                    response.data.success === true
                ) {

                    c.success =
                        response.data.message ||
                        "Interview evaluation saved successfully.";


                    /*
                     * Update displayed score
                     */

                    if (
                        response.data.overall_score !==
                        undefined
                    ) {

                        c.overallScore =
                            response.data.overall_score;

                    }


                    /*
                     * Redirect after short delay
                     */

                    setTimeout(
                        function() {

                            $window.location.href =
                                "?id=campus360_recruiter_interviews";

                        },
                        1200
                    );

                }

                else {

                    c.error =
                        (
                            response.data &&
                            response.data.error
                        ) ||
                        "Unable to save evaluation.";

                }

            },

            function(error) {

                c.saving = false;


                c.error =
                    "Server error while saving evaluation.";

            }

        );

    };

};

sp_widget.css:
.evaluation-page {
  max-width: 1100px;
  margin: 30px auto;
  padding: 0 20px 60px;
  color: #102a56;
}


/* HEADER */

.page-header {
  background: #ffffff;
  border: 1px solid #e1e7f2;
  border-radius: 18px;
  padding: 30px;
  margin-bottom: 22px;

  display: flex;
  justify-content: space-between;
  align-items: center;

  box-shadow: 0 8px 25px rgba(30,55,90,.06);
}

.eyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 2px;
  color: #5368e8;
}

.page-header h1 {
  margin: 8px 0 5px;
  font-size: 28px;
}

.page-header p {
  margin: 0;
  color: #7888a3;
  font-size: 14px;
}


/* CARD */

.card {
  background: #ffffff;
  border: 1px solid #e1e7f2;
  border-radius: 18px;
  padding: 28px;
  margin-bottom: 22px;

  box-shadow: 0 8px 25px rgba(30,55,90,.05);
}


/* SECTION TITLE */

.section-title {
  border-bottom: 1px solid #e8edf5;
  padding-bottom: 20px;
  margin-bottom: 25px;
}

.section-title h2 {
  margin: 7px 0 5px;
  font-size: 20px;
}

.section-title p {
  margin: 0;
  color: #7888a3;
  font-size: 13px;
}


/* DETAILS */

.details-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 15px;
}

.detail-box {
  background: #f8faff;
  border: 1px solid #e1e7f2;
  border-radius: 10px;
  padding: 18px;
}

.detail-box .label {
  display: block;
  font-size: 9px;
  letter-spacing: 1px;
  color: #71809b;
  margin-bottom: 8px;
}

.detail-box strong {
  font-size: 14px;
  color: #183561;
}


/* RATING */

.rating-group {
  margin-bottom: 28px;
}

.rating-group label,
.form-group label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 10px;
}

.rating-group label span,
.form-group label span {
  color: #e05252;
}

.rating-buttons {
  display: flex;
  gap: 10px;
}

.rating-buttons button {
  width: 40px;
  height: 40px;

  border-radius: 8px;

  border: 1px solid #d5deed;
  background: #ffffff;

  color: #24395f;

  cursor: pointer;
}

.rating-buttons button:hover {
  border-color: #5368e8;
}

.rating-buttons button.selected {
  background: #5368e8;
  border-color: #5368e8;
  color: #ffffff;
}

.rating-group small {
  display: block;
  margin-top: 7px;
  color: #8794aa;
  font-size: 10px;
}


/* SCORE */

.score-box {
  display: flex;
  justify-content: space-between;
  align-items: center;

  padding: 22px;

  background: #f7f9ff;

  border: 1px solid #dce3f5;
  border-radius: 12px;

  margin: 25px 0;
}

.score-title {
  font-weight: 700;
  font-size: 15px;
}

.score-description {
  margin-top: 5px;
  font-size: 11px;
  color: #7b89a2;
}

.score-value {
  font-size: 27px;
  font-weight: 700;
  color: #5368e8;
}

.score-value span {
  font-size: 13px;
  color: #8a96aa;
}


/* FORM */

.form-group {
  margin-bottom: 22px;
}

.form-group select,
.form-group input,
.form-group textarea {
  width: 100%;
  box-sizing: border-box;

  border: 1px solid #d6deeb;
  border-radius: 8px;

  padding: 12px;

  font-size: 13px;

  color: #24395f;

  background: #ffffff;
}

.form-group select,
.form-group input {
  height: 44px;
}

.form-group textarea {
  min-height: 120px;
  resize: vertical;
}

.form-group input[readonly] {
  background: #f7f9fc;
}


/* BUTTONS */

.form-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;

  border-top: 1px solid #e8edf5;

  padding-top: 22px;

  margin-top: 25px;
}

.btn {
  height: 42px;
  padding: 0 18px;

  border-radius: 8px;

  font-size: 13px;
  font-weight: 600;

  cursor: pointer;
}

.btn-primary {
  background: #5368e8;
  color: #ffffff;
  border: 1px solid #5368e8;
}

.btn-primary:hover {
  background: #4056d5;
}

.btn-secondary {
  background: #ffffff;
  color: #5368e8;
  border: 1px solid #ccd5e5;
}


/* MESSAGES */

.error-message {
  margin-top: 20px;

  padding: 13px 15px;

  background: #fff1f1;

  border: 1px solid #ffd0d0;

  color: #c33d3d;

  border-radius: 8px;

  font-size: 13px;
}

.success-message {
  margin-top: 20px;

  padding: 13px 15px;

  background: #effaf3;

  border: 1px solid #c9ecd5;

  color: #25804a;

  border-radius: 8px;

  font-size: 13px;
}


/* MOBILE */

@media(max-width:768px) {

  .page-header {
    flex-direction: column;
    align-items: flex-start;
    gap: 18px;
  }

  .details-grid {
    grid-template-columns: 1fr;
  }

  .score-box {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .form-actions {
    flex-direction: column;
  }

  .btn {
    width: 100%;
  }

}

sp_widget.script:
(function() {

    // ============================================================
    // INITIAL DATA
    // ============================================================

    data.interview = null;

    data.success = false;

    data.error = "";

    data.message = "";

    data.overall_score = 0;

    data.loading = false;


    // ============================================================
    // TABLE
    // ============================================================

    var TABLE =
        "x_snc_campus360_recruiter_interview";


    // ============================================================
    // GET INTERVIEW SYS_ID
    // ============================================================

    var interviewSysId =
        $sp.getParameter("interview_sys_id");


    // ============================================================
    // LOAD INTERVIEW
    // ============================================================

    if (interviewSysId) {

        var interviewGR =
            new GlideRecord(TABLE);


        if (interviewGR.get(interviewSysId)) {

            data.interview = {

                sys_id:
                    interviewGR.getUniqueValue(),


                student:
                    interviewGR.getValue(
                        "student"
                    ),


                student_display:
                    interviewGR.getDisplayValue(
                        "student"
                    ),


                opportunity:
                    interviewGR.getValue(
                        "opportunity"
                    ),


                opportunity_display:
                    interviewGR.getDisplayValue(
                        "opportunity"
                    ),


                application:
                    interviewGR.getValue(
                        "application"
                    ),


                application_display:
                    interviewGR.getDisplayValue(
                        "application"
                    ),


                interview_round:
                    interviewGR.getValue(
                        "interview_round"
                    ),


                interview_round_display:
                    interviewGR.getDisplayValue(
                        "interview_round"
                    ),


                interview_date:
                    interviewGR.getDisplayValue(
                        "interview_date"
                    ),


                interviewer:
                    interviewGR.getDisplayValue(
                        "interviewer"
                    )

            };

        }

        else {

            data.error =
                "Interview record could not be found.";

        }

    }

    else {

        data.error =
            "Interview record ID is missing.";

    }


    // ============================================================
    // SAVE EVALUATION
    // ============================================================

    if (
        input &&
        input.action === "save_evaluation"
    ) {


        // ========================================================
        // INPUT
        // ========================================================

        var form =
            input.form;


        var sysId =
            input.interview_sys_id;


        // ========================================================
        // VALIDATE SYS_ID
        // ========================================================

        if (!sysId) {

            data.success = false;

            data.error =
                "Interview record ID is missing.";

            return;

        }


        // ========================================================
        // VALIDATE FORM
        // ========================================================

        if (!form) {

            data.success = false;

            data.error =
                "Evaluation data is missing.";

            return;

        }


        // ========================================================
        // GET RECORD
        // ========================================================

        var gr =
            new GlideRecord(TABLE);


        if (!gr.get(sysId)) {

            data.success = false;

            data.error =
                "Interview record not found.";

            return;

        }


        // ========================================================
        // CHECK DATABASE FIELDS
        // ========================================================

        var requiredFields = [

            "technical_score",

            "problem_solving_score",

            "communication_score",

            "overall_score",

            "recommendation",

            "evaluation_feedback",

            "evaluation_status",

            "status",

            "result"

        ];


        for (
            var i = 0;
            i < requiredFields.length;
            i++
        ) {

            var fieldName =
                requiredFields[i];


            if (
                !gr.isValidField(
                    fieldName
                )
            ) {

                data.success = false;

                data.error =
                    "Database field does not exist: " +
                    fieldName;

                return;

            }

        }


        // ========================================================
        // READ SCORES
        // ========================================================

        var technical =
            parseInt(
                form.technical_score,
                10
            );


        var problemSolving =
            parseInt(
                form.problem_solving_score,
                10
            );


        var communication =
            parseInt(
                form.communication_score,
                10
            );


        // ========================================================
        // VALIDATE SCORES
        // ========================================================

        if (
            isNaN(technical) ||
            isNaN(problemSolving) ||
            isNaN(communication)
        ) {

            data.success = false;

            data.error =
                "Evaluation scores must be valid numbers.";

            return;

        }


        if (
            technical < 1 ||
            technical > 5 ||
            problemSolving < 1 ||
            problemSolving > 5 ||
            communication < 1 ||
            communication > 5
        ) {

            data.success = false;

            data.error =
                "All evaluation scores must be between 1 and 5.";

            return;

        }


        // ========================================================
        // CALCULATE OVERALL SCORE
        // ========================================================

        var total =
            technical +
            problemSolving +
            communication;


        var overallScore =
            Math.round(
                (total / 15) * 100
            );


        data.overall_score =
            overallScore;


        // ========================================================
        // VALIDATE RECOMMENDATION
        // ========================================================

        var recommendation =
            String(
                form.recommendation || ""
            );


        if (
            recommendation !==
            "strongly_recommended" &&

            recommendation !==
            "recommended" &&

            recommendation !==
            "not_recommended"
        ) {

            data.success = false;

            data.error =
                "Please select a valid recommendation.";

            return;

        }


        // ========================================================
        // VALIDATE FEEDBACK
        // ========================================================

        var evaluationFeedback =
            String(
                form.evaluation_feedback || ""
            ).trim();


        if (!evaluationFeedback) {

            data.success = false;

            data.error =
                "Please enter interview feedback.";

            return;

        }


        // ========================================================
        // SET TECHNICAL SCORE
        // ========================================================

        gr.setValue(
            "technical_score",
            technical
        );


        // ========================================================
        // SET PROBLEM SOLVING SCORE
        // ========================================================

        gr.setValue(
            "problem_solving_score",
            problemSolving
        );


        // ========================================================
        // SET COMMUNICATION SCORE
        // ========================================================

        gr.setValue(
            "communication_score",
            communication
        );


        // ========================================================
        // SET OVERALL SCORE
        // ========================================================

        gr.setValue(
            "overall_score",
            overallScore
        );


        // ========================================================
        // SET RECOMMENDATION
        // ========================================================

        gr.setValue(
            "recommendation",
            recommendation
        );


        // ========================================================
        // SET EVALUATION FEEDBACK
        // ========================================================

        gr.setValue(
            "evaluation_feedback",
            evaluationFeedback
        );


        // ========================================================
        // SET EVALUATION STATUS
        //
        // Choice:
        // Pending   = pending
        // Evaluated = evaluated
        // ========================================================

        gr.setValue(
            "evaluation_status",
            "evaluated"
        );


        // ========================================================
        // SET INTERVIEW STATUS
        //
        // Scheduled -> Completed
        // ========================================================

        gr.setValue(
            "status",
            "completed"
        );


        // ========================================================
        // SET RESULT
        //
        // Strongly Recommended -> Selected
        // Recommended          -> Selected
        // Not Recommended      -> Rejected
        // ========================================================

        if (
            recommendation ===
            "strongly_recommended" ||

            recommendation ===
            "recommended"
        ) {

            gr.setValue(
                "result",
                "selected"
            );

        }

        else {

            gr.setValue(
                "result",
                "rejected"
            );

        }


        // ========================================================
        // UPDATE RECORD
        // ========================================================

        try {

            var updatedSysId =
                gr.update();


            // ====================================================
            // SUCCESS
            // ====================================================

            if (updatedSysId) {

                data.success =
                    true;


                data.message =
                    "Interview evaluation saved successfully.";


                data.overall_score =
                    overallScore;


                /*
                 * Return updated values for debugging/confirmation
                 */

                data.saved = {

                    technical_score:
                        technical,

                    problem_solving_score:
                        problemSolving,

                    communication_score:
                        communication,

                    overall_score:
                        overallScore,

                    recommendation:
                        recommendation,

                    evaluation_status:
                        "evaluated",

                    status:
                        "completed",

                    result:
                        (
                            recommendation ===
                                "not_recommended"
                        )
                            ? "rejected"
                            : "selected"

                };

            }

            else {

                data.success =
                    false;


                data.error =
                    "ServiceNow could not update the interview record. Check the table ACLs and field permissions.";

            }

        }


        catch (e) {

            data.success =
                false;


            data.error =
                "Save failed: " +
                e.message;

        }

    }

})();
